class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        MAXD = 302
        g = [[0] * (MAXD + 1) for _ in range(301)]
        for v in range(301):
            g[v][MAXD] = 1
        seen = set()
        ans = 1
        for x in nums:
            tmp = [0] * (MAXD + 1)
            tmp[MAXD] = 1
            for y in seen:
                d = abs(x - y)
                c = g[y][d] + 1
                if c > tmp[d]:
                    tmp[d] = c
            for d in range(MAXD - 1, 0, -1):
                if tmp[d + 1] > tmp[d]:
                    tmp[d] = tmp[d + 1]
            row = g[x]
            for d in range(1, MAXD + 1):
                if tmp[d] > row[d]:
                    row[d] = tmp[d]
            seen.add(x)
            if tmp[1] > ans:
                ans = tmp[1]
        return ans

