class Solution {
public:
    int longestSubsequence(vector<int>& nums) {
        const int MAXD = 302;
        static int g[301][MAXD + 1] = {};
        for (int v = 0; v <= 300; v++) g[v][MAXD] = 1;
        bool seen[301] = {};
        int ans = 1;
        for (int x : nums) {
            vector<int> tmp(MAXD + 1, 0);
            tmp[MAXD] = 1;
            for (int y = 0; y <= 300; y++) {
                if (!seen[y]) continue;
                int d = abs(x - y);
                tmp[d] = max(tmp[d], g[y][d] + 1);
            }
            for (int d = MAXD - 1; d >= 1; d--) tmp[d] = max(tmp[d], tmp[d + 1]);
            for (int d = 1; d <= MAXD; d++) g[x][d] = max(g[x][d], tmp[d]);
            seen[x] = true;
            ans = max(ans, tmp[1]);
        }
        return ans;
    }
};

