class Solution {
    public int longestSubsequence(int[] nums) {
        final int MAXD = 302;
        int[][] g = new int[301][MAXD + 1];
        for (int v = 0; v <= 300; v++) g[v][MAXD] = 1;
        boolean[] seen = new boolean[301];
        int ans = 1;
        for (int x : nums) {
            int[] tmp = new int[MAXD + 1];
            tmp[MAXD] = 1;
            for (int y = 0; y <= 300; y++) {
                if (!seen[y]) continue;
                int d = Math.abs(x - y);
                tmp[d] = Math.max(tmp[d], g[y][d] + 1);
            }
            for (int d = MAXD - 1; d >= 1; d--) tmp[d] = Math.max(tmp[d], tmp[d + 1]);
            for (int d = 1; d <= MAXD; d++) g[x][d] = Math.max(g[x][d], tmp[d]);
            seen[x] = true;
            ans = Math.max(ans, tmp[1]);
        }
        return ans;
    }
}

