var longestSubsequence = function(nums) {
    const MAXD = 302;
    const g = Array.from({length: 301}, () => new Array(MAXD + 1).fill(0));
    for (let v = 0; v <= 300; v++) g[v][MAXD] = 1;
    const seen = new Array(301).fill(false);
    let ans = 1;
    for (const x of nums) {
        const tmp = new Array(MAXD + 1).fill(0);
        tmp[MAXD] = 1;
        for (let y = 0; y <= 300; y++) {
            if (!seen[y]) continue;
            const d = Math.abs(x - y);
            if (g[y][d] + 1 > tmp[d]) tmp[d] = g[y][d] + 1;
        }
        for (let d = MAXD - 1; d >= 1; d--) tmp[d] = Math.max(tmp[d], tmp[d + 1]);
        for (let d = 1; d <= MAXD; d++) if (tmp[d] > g[x][d]) g[x][d] = tmp[d];
        seen[x] = true;
        ans = Math.max(ans, tmp[1]);
    }
    return ans;
};
